def parse_ini(text):
    lines = text.split('\n')
    result = {}
    current_section = None

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith('[') and line.endswith(']'):
            section = line[1:-1]
        elif line.startswith('[') and line.endswith(','):
            section, key = line[1:-2].split('=')
        else:
            if line.startswith('[') and line.endswith(','):
                section, key = line[1:-2].split('=')  # no space before =
            else:
                key, value = line.split('=')
        if section and key:
            if current_section is not None:
                result[section] = {key: value}
                current_section = section
            else:
                result[section] = {key: value}
        elif line.startswith('[') and line.endWith(','):
            section = line[1:-2]
            if section in result:
                result[section] = {}
    return result
```

