/**
 * Removes duplicates by a specific key in an array, keeping the first occurrence.
 * @param {Array} arr - The array to process.
 * @param {Function} keyFn - A function that returns a unique identifier for each element.
 *                             The value of the property used to identify the key in the array.
    * 
* @returns {Array} A new array with duplicates removed, keeping the first occurrence of each key.
 */
function uniqueBy(arr, keyFn) {
  const result = [];
  const seen = new Set();

  arr.forEach(item => {
    const key = keyFn(item);
    if (!seen.has(key)) {
      result.push(item);
      seen.add(key);
    }
  });

  return result;
}

module.exports = uniqueBy;
