```javascript
const { partition } = require('@std/array');
const { strict as assert } = require('assert');

/**
 * Partitions the given array into two arrays based on the provided predicate.
 * The first array contains elements for which the predicate returned true,
 * and the second array contains the remaining elements.
 *
 * @param {Array} arr - The input array of elements to be partitioned.
 * @param {Function} pred - A function that returns a boolean indicating whether an element should be in the first array.
 * @returns An array with two elements: [matching, notMatching].
 */
function partition(arr, pred) {
  const result = [[], []];

  for (const item of arr) {
    if (pred(item)) {
      result[0].push(item);
    } else {
          result[1].push(item);
        }
      }

  return [result[0], result[1]];
}

module.exports = partition;
```

### Explanation:
- The function `partition` takes an array and a predicate function as arguments.
- It initializes two empty arrays: `matching` and `notMatching`.
- It iterates over each element in the input array.
- For each element, it checks if the predicate returns `true`. If so, it adds the element to the `matching` array; otherwise, it adds it to the `notMatching` array.
- Finally, it returns an array containing the `matching` and `notMatching` arrays.

### Usage:
```javascript
const { partition } = require('./path/to/partition');

// Example usage:
const arr = [1, 2, 3, 4, 5];
const [matching, notMatching] = partition(arr, (item) => item % 2 === 0);
console.log(matching); // [2, 4]
console.log(notMatching); // [1, 3, 5]
```

This code defines a function `partition` that takes an array and a predicate function, then returns an array with two elements: one containing the elements for which the predicate returned `true`, and the other containing the remaining elements.

