// countOccurrences.js

/**
 * Count the number of non-overlapping occurrences of a substring in a given string.

* @param {string} s - The main string.
* @param {string} sub - The substring to search for.
* @return {number} The number of non-overlapping occurrences of the substring in the main string.
*/
function countOccurrences(s, sub) {
  let count = 0;
  for (let i = 0; i < s.length - sub.length + 1; ) {
    if (s.substring(i, i + sub.length) === sub) {
      count++;
      i += sub.length;
    } else {
      i++;
    }
  }
  return count;
}

module.exports = countOccurrences;
