为了在 TypeScript 中实现 `Reducer` 类型和 `run` 函数，我们需要定义 `Reducer` 类型和一个辅助函数来处理状态转换。以下是完整的 TypeScript 代码：

```typescript
type Reducer<S, A> = (s: S, a: A) => S;

function run<S, A>(r: Reducer<S, A>, init: S, actions: A[]): S {
  return actions.reduce((s, action) => r(s, { ...a, [action.key]: a[action.key] }), s);
}

// 示例用法：
// type State = { count: number, text: string };
// const initialState: State = { count: 0, text: '' };

// Define the action types and their corresponding values
const actions = {
  INCREASE: { type: 'INCREASE' as const, value: 1 },
  DECREASE: { type: 'DECREASE' as const, value: -1 },
  SET_TEXT: (value: string) => ({ type: 'SET_TEXT', value } as const, value)
};

// Example usage:
const state = run(
  (s, action) => {
    switch (action.type) {
      case 'INCREASE__':
        return { ...s, count: s.count + action.value };
      case 'DECREASE__':
        return { ...s, count: s.count - action.value };
      case 'SET_TEXT':
        return { ...s, text: action.value };
      default:
        throw new Error(`Unknown action type: ${action.type}`);
    }
  },
  { count: 0, text: '' }, // Initial state
  [actions.INCREASE, actions.SET_TEXT('Hello, World!')] as const
);
console.log(state); // { count: 0, text: 'Hello, World!' }
```

