import React, { useRef, useEffect } from 'react';
import { View, StyleSheet, Text, Dimensions } from 'react-native';

const MyComponent = () => {
  const { width, height } = useRef(Dimensions.get('window'));

  useEffect(() => {
    const handleResize = () => {
      const { width: windowWidth, height: windowHeight } = useRef(Dimensions.get('window'));

      // Your code to handle the resizing
      console.log(`Window width: ${windowWidth}, Height: ${height}`);
    };

    // Add a resize event listener
    window.addEventListener('resize', handleResize);

    return () => {
      // Remove the event listener on cleanup
      window.removeEventListener('resize', handleResize);
    };
  }, [height]);

  return <View style={styles.container} />;
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
});

export default MyComponent;
```

